"""Pure-Python FairPlay setup phase — no native dependencies.

Runs the p1/p2 session setup (operate(p1) + operate(p2)) that produces
the entry state for ``_OowSGu``. Combined with ``fp_decrypt``, this
eliminates ALL native dependencies (unicorn, lief, capstone) and the
73 MB firmware dylib bundle.

Public API::

    from pylibairplay.fp_setup import run_setup
    snap = run_setup(p1_bytes, p2_bytes, ekey_bytes)
    # snap is the dict that fp_decrypt.decrypt_ekey() expects
"""
from __future__ import annotations

import base64
import gzip
import json
import struct

from . import fp_decrypt as _d

MASK64 = _d.MASK64
MASK32 = _d.MASK32

def _decompress(b64: str) -> bytes:
    return gzip.decompress(base64.b64decode(b64))

