def _call_hidden(cpu, mem, addr, heap_ptr, depth=0):
    """Execute a hidden function call chain recursively."""
    if depth > 10:
        return heap_ptr
    # The library init function (0x2455b0560) is too complex (hundreds of blocks
    # with loops). Its effects are captured in _INIT_PATCHES and applied at block 30.
    if addr == 0x2455b0560:
        cpu.setreg("x0", 0)
        return heap_ptr
    while addr is not None:
        instrs = _HIDDEN_BLOCKS.get(addr)
        if instrs is None:
            return heap_ptr
        next_addr = None
        for a, s, mn, ops in instrs:
            if mn in ("ret", "retab", "retaa"):
                return heap_ptr
            if mn in ("blr", "blraa", "blrab"):
                cpu.setreg("x30", a + s)
                target_reg = ops.split(",")[0].strip()
                target = cpu.getreg(target_reg)
                kind = _STUBS.get(target)
                if kind:
                    heap_ptr = _apply_stub(kind, cpu, mem, heap_ptr)
                elif target in _HIDDEN_BLOCKS:
                    heap_ptr = _call_hidden(cpu, mem, target, heap_ptr, depth + 1)
                else:
                    cpu.setreg("x0", 0)
                next_addr = a + s
                break
            if mn in ("br", "braa", "brab"):
                target_reg = ops.split(",")[0].strip()
                target = cpu.getreg(target_reg)
                if target in _HIDDEN_BLOCKS:
                    next_addr = target
                else:
                    return heap_ptr
                break
            if mn == "cbz":
                reg = ops.split(",")[0].strip()
                if cpu.getreg(reg) == 0:
                    target = _d._parse_imm(ops.split(",")[1].strip())
                    if target in _HIDDEN_BLOCKS:
                        next_addr = target
                        break
                    return heap_ptr
                continue
            if mn == "cbnz":
                reg = ops.split(",")[0].strip()
                if cpu.getreg(reg) != 0:
                    target = _d._parse_imm(ops.split(",")[1].strip())
                    if target in _HIDDEN_BLOCKS:
                        next_addr = target
                        break
                    return heap_ptr
                continue
            if mn in ("b",):
                break
            if mn.startswith("b."):
                cc = mn[2:]
                if cpu.cond_true(cc):
                    break
                continue
            _d._exec_insn(cpu, mem, mn, ops)
        addr = next_addr
    return heap_ptr


def _exec_block_with_stubs(cpu, mem, instrs, heap_ptr):
    """Execute a block, intercepting BLR targets that are known stubs or hidden blocks."""
    for insn_tuple in instrs:
        addr, size, mn, ops = insn_tuple

        if mn in ("b", "br", "braa", "brab", "ret", "retab", "retaa"):
            break
        if mn in ("bl", "blr", "blraa", "blrab"):
            cpu.setreg("x30", addr + size)
            if mn in ("blr", "blraa", "blrab"):
                target_reg = ops.split(",")[0].strip()
                target = cpu.getreg(target_reg)
                kind = _STUBS.get(target)
                if kind:
                    heap_ptr = _apply_stub(kind, cpu, mem, heap_ptr)
                elif target in _HIDDEN_BLOCKS:
                    heap_ptr = _call_hidden(cpu, mem, target, heap_ptr)
                elif not (_CODE_LO <= target <= _CODE_HI) and target > 0x1000:
                    cpu.setreg("x0", 0)
            break

        if mn.startswith("b."):
            cc = mn[2:]
            if cpu.cond_true(cc):
                break
            continue
        if mn == "cbz":
            reg = ops.split(",")[0].strip()
            if cpu.getreg(reg) == 0:
                break
            continue
        if mn == "cbnz":
            reg = ops.split(",")[0].strip()
            if cpu.getreg(reg) != 0:
                break
            continue
        if mn == "tbz":
            p = [x.strip() for x in ops.split(",")]
            val = cpu.getreg(p[0])
            bit = _d._parse_imm(p[1])
            if not (val & (1 << bit)):
                break
            continue
        if mn == "tbnz":
            p = [x.strip() for x in ops.split(",")]
            val = cpu.getreg(p[0])
            bit = _d._parse_imm(p[1])
            if val & (1 << bit):
                break
            continue

        try:
            _d._exec_insn(cpu, mem, mn, ops)
        except Exception as e:
            print(f"FAIL at 0x{addr:x}: {mn} {ops} -> {e}")
            raise

    return heap_ptr


_cache = {}

def _get_blocks():
    if "blocks" not in _cache:
        raw = json.loads(_decompress(_SETUP_BLOCKS_B64).decode())
        _cache["blocks"] = {int(k, 16): [tuple(i) for i in v] for k, v in raw.items()}
    return _cache["blocks"]

def _get_seq(selector):
    key = f"seq_{selector}"
    if key not in _cache:
        b64 = _SEQ3_B64 if selector == 3 else _SEQ0_B64
        _cache[key] = json.loads(_decompress(b64).decode())
    return _cache[key]

def _snapshot_state(cpu, mem, heap_ptr, prev_addr):
    """Deep-copy CPU + Memory state for caching between sessions."""
    return {
        'x': list(cpu.x),
        'sp': cpu.sp,
        'flags': (cpu.flag_n, cpu.flag_z, cpu.flag_c, cpu.flag_v),
        'regions': [(base, end, bytes(buf)) for base, end, buf in mem.regions],
        'heap_ptr': heap_ptr,
        'prev_addr': prev_addr,
    }


def _restore_state(snap):
    """Restore CPU + Memory from a snapshot (returns fresh mutable copies)."""
    mem = _d.Memory()
    for base, end, data in snap['regions']:
        mem.map(base, data)
    cpu = _d.CPU(mem)
    cpu.x = list(snap['x'])
    cpu.sp = snap['sp']
    cpu.flag_n, cpu.flag_z, cpu.flag_c, cpu.flag_v = snap['flags']
    return cpu, mem, snap['heap_ptr'], snap['prev_addr']


def _setup_operate(cpu, mem, state_ptr, inbuf, inlen):
    """Set registers for an operate(input) call."""
    mem.write(_OUT_SLOT, b"\x00" * 8)
    mem.write(_OUTLEN_SLOT, b"\x00" * 8)
    mem.write(_FLAG_SLOT, b"\x00")
    cpu.setreg("x0", 3)
    cpu.setreg("x1", _SCRATCH)
    cpu.setreg("x2", state_ptr)
    cpu.setreg("x3", inbuf)
    cpu.setreg("x4", inlen)
    cpu.setreg("x5", _OUT_SLOT)
    cpu.setreg("x6", _OUTLEN_SLOT)
    cpu.setreg("x7", _FLAG_SLOT)
    cpu.setreg("x30", 0)
    for i in range(19, 31):
        cpu.setreg(f"x{i}", 0)
    cpu.sp = _WARMUP_SP


def _run_blocks(cpu, mem, blocks, seq, start_block, heap_ptr, prev_addr,
                mark_p2=None, mark_p2_fn=None, init_patch=None):
    """Execute a range of blocks from seq. Returns (heap_ptr, prev_addr)."""
    _INIT_BLR_BLOCK = 29
    init_applied = start_block > _INIT_BLR_BLOCK
    block_count = start_block

    for entry in seq:
        addr = int(entry[0], 16)
        repeat = entry[1]

        if mark_p2 is not None and block_count == mark_p2 and mark_p2_fn:
            mark_p2_fn()

        if addr == 0x24559bcfc and prev_addr == 0x24559bb38:
            cpu.setreg("x0", 0)

        if addr not in blocks:
            block_count += repeat
            prev_addr = addr
            continue
        instrs = blocks[addr]
        for _ in range(repeat):
            if mark_p2 is not None and block_count == mark_p2 and mark_p2_fn:
                mark_p2_fn()
            block_count += 1
            heap_ptr = _exec_block_with_stubs(cpu, mem, instrs, heap_ptr)

            if block_count == _INIT_BLR_BLOCK + 1 and not init_applied and init_patch:
                init_applied = True
                for patch_addr, patch_bytes in init_patch['mem']:
                    mem.write(patch_addr, patch_bytes)
                for rname, rval in init_patch['regs'].items():
                    cpu.setreg(rname, rval)
                cpu.sp = init_patch['sp']

        prev_addr = addr

    return heap_ptr, prev_addr


def run_setup(p1: bytes, p2: bytes, ekey: bytes) -> dict:
    """Run the FairPlay setup phase and return the _OowSGu entry state.

    Returns a dict with keys: regs, stack, heap, scratch, bss, common, data
    suitable for passing to ``fp_decrypt.decrypt_ekey()``.

    The p1 phase (~59% of work) is deterministic per selector and cached after
    the first run, cutting subsequent sessions from ~8s to ~3s.
    """
    selector = p1[14] if len(p1) > 14 else 0
    _MARK_P2 = 59422 if selector == 3 else 59421

    blocks = _get_blocks()
    seq = _get_seq(selector)
    p1_cache_key = f"p1_{selector}"
    cached = _cache.get(p1_cache_key)

    if cached is not None:
        # Fast path: restore from post-p1 snapshot, run only p2
        cpu, mem, heap_ptr, prev_addr = _restore_state(cached['snap'])
        p2_seq = seq[cached['seq_idx']:]
        mem.write(_IN2, p2)
        mem.write(_EKB, ekey)
        state_ptr = mem.read_u64(_STATE_SLOT)
        _setup_operate(cpu, mem, state_ptr, _IN2, len(p2))
        heap_ptr, _ = _run_blocks(cpu, mem, blocks, p2_seq, _MARK_P2, heap_ptr, prev_addr)
    else:
        # Full path: build memory, run p1 + p2, cache p1 state at boundary
        mem = _d.Memory()
        mem.map(0x100000000, _decompress(_WARMUP_STACK_B64))
        mem.map(0x400000000, _decompress(_WARMUP_HEAP_B64))
        _scratch = bytearray(_decompress(_WARMUP_SCRATCH_B64))
        _scratch[0x18000:0x28000] = b"\x00" * 0x10000
        mem.map(0x200000000, bytes(_scratch))
        mem.map(_d._CONST_START, _decompress(_d._CONST_B64))
        mem.map(_d._AUTH_CONST_START, _decompress(_d._AUTH_CONST_B64))
        mem.map(0x27e498000, _decompress(_WARMUP_DATA_B64))

        stub_page = bytearray(0x4000)
        stub_page[0:4] = struct.pack("<I", 0xd65f03c0)
        mem.map(0, bytes(stub_page))

        mem.write(_IN1, p1)
        mem.write(_IN2, p2)
        mem.write(_EKB, ekey)

        cpu = _d.CPU(mem)
        cpu.sp = _WARMUP_SP
        cpu.setreg("x8", 0xb4848817)
        cpu.setreg("x9", 0xd65f03c0)
        cpu.setreg("x10", 0xd65f03c0)
        cpu.setreg("x11", 0xb4848817)
        cpu.setreg("x12", 0x24553f22c)
        cpu.setreg("x13", 0x3ef90)
        cpu.setreg("x14", 0xb2)
        cpu.setreg("x15", 0x245693710)
        cpu.setreg("x16", 0x245679310)
        cpu.setreg("x17", 0x307f)

        state_ptr = mem.read_u64(_STATE_SLOT)
        init_patch = _INIT_PATCHES.get(selector, _INIT_PATCHES.get(0))

        # Run p1 blocks (up to _MARK_P2)
        _setup_operate(cpu, mem, state_ptr, _IN1, len(p1))
        p1_seq = seq[:_MARK_P2]  # entries before the boundary
        heap_ptr = 0x400020000
        # Find the exact seq index where _MARK_P2 falls
        bc = 0
        seq_idx = 0
        for idx, entry in enumerate(seq):
            addr_val = int(entry[0], 16)
            repeat = entry[1]
            if addr_val not in blocks:
                next_bc = bc + repeat
            else:
                next_bc = bc + repeat
            if next_bc >= _MARK_P2:
                seq_idx = idx
                break
            bc = next_bc

        heap_ptr, prev_addr = _run_blocks(
            cpu, mem, blocks, seq[:seq_idx], 0, heap_ptr, 0,
            init_patch=init_patch)

        # Cache the post-p1 state
        _cache[p1_cache_key] = {
            'snap': _snapshot_state(cpu, mem, heap_ptr, prev_addr),
            'seq_idx': seq_idx,
        }

        # Run p2 blocks
        _setup_operate(cpu, mem, state_ptr, _IN2, len(p2))
        heap_ptr, _ = _run_blocks(
            cpu, mem, blocks, seq[seq_idx:], _MARK_P2, heap_ptr, prev_addr)

    # Build the entry state for _OowSGu
    state_ptr = mem.read_u64(_STATE_SLOT)
    mem.write(_O, b"\x00" * 8)
    mem.write(_OL, b"\x00" * 8)

    regs = {
        "x0": state_ptr, "x1": _EKB, "x2": len(ekey),
        "x3": _O, "x4": _OL, "x5": 0, "x6": 0, "x7": 0,
    }
    for i in range(8, 31):
        regs[f"x{i}"] = cpu.x[i]
    regs["sp"] = cpu.sp

    return {
        "regs": regs,
        "stack": bytes(mem.read(0x100000000, 0x40000)),
        "heap": bytes(mem.read(0x400000000, 0x20000)),
        "scratch": bytes(mem.read(0x200000000, 0x28000)),
        "data": bytes(mem.read(0x27e49b020, 0x17b60)),
        "bss": bytes(mem.read(0x27e4b2b80, 0x5d8)),
        "common": bytes(mem.read(0x27e4b3158, 0xa84)),
    }


def decrypt_ekey_full(p1: bytes, p2: bytes, ekey: bytes) -> bytes:
    """Full pure-Python FairPlay ekey decrypt: setup + _OowSGu.

    No emulator, no native dependencies, no firmware dylibs needed.
    """
    snap = run_setup(p1, p2, ekey)
    return _d.decrypt_ekey(snap)
